export const groupDigits = (value) => String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const defaults = new Map();
export function loginText(lang = 'en') {
    const requested = lang.toLowerCase().split('-')[0] ?? 'en';
    const locale = Object.hasOwn(LOGIN_STRINGS, requested) ? requested : 'en';
    const cached = defaults.get(locale);
    if (cached)
        return cached;
    const own = { ...LOGIN_STRINGS[locale],
        ...ACCOUNT_STRINGS[locale],
        ...FEATURE_STRINGS[locale] };
    const en = { ...LOGIN_STRINGS.en, ...ACCOUNT_STRINGS.en, ...FEATURE_STRINGS.en };
    const text = (key, params = {}) => {
        const category = typeof params['count'] === 'number'
            ? new Intl.PluralRules(locale).select(params['count']) : undefined;
        return ((category ? own[`${key}.@${category}`] ?? own[`${key}.@other`] : undefined)
            ?? own[key] ?? en[key] ?? key)
            .replace(/\{(\w+)\}/g, (match, name) => (Object.hasOwn(params, name) ? String(params[name]) : match));
    };
    defaults.set(locale, text);
    return text;
}
export function kitText(game, lang = 'en') {
    const kit = loginText(lang);
    if (!game)
        return kit;
    return (key, params) => {
        const value = game(key, params);
        return (value === key ? kit(key, params) : value)
            .replace(/\{(\w+)\}/g, (match, name) => params && Object.hasOwn(params, name) ? String(params[name]) : match);
    };
}
export const clock = (ms) => {
    const total = Math.max(0, Math.ceil(ms / 1000));
    return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
};
export function loginErrorText(text, error, provider = '') {
    if (!error)
        return undefined;
    if (error.code === 'AUTH_CODE_INVALID' && error.attemptsLeft !== undefined) {
        return text('kit.login.code.attempts', { count: error.attemptsLeft });
    }
    const key = `kit.login.error.${error.code}`;
    const value = text(key, { time: clock(error.retryAfterMs ?? 0), provider });
    return value === key ? text('kit.login.error.default') : value;
}
